startDecorations(); startWindowMenu();
globalThis.sel = () => windowMenu.current ? [windowMenu.current.nav.depth, windowMenu.current.nav.selected()?.label ?? null] : null;
globalThis.card = () => { const m = windowMenu.current; if (!m) return null; const p = m.panel;
return { x: p.x, y: p.y, width: p.width, height: p.height, secure: [p.secure, m.secure], rows: p.rows.map((r) => [r.label, r.enabled, r.checked]) }; };
globalThis.row = (label) => windowMenu.current.panel.rows.find((r) => r.label === label).node;
